  detailed_macrocycles = '[{"id":"macro_1","nome":"Fase de Base/Adaptação","meses":[1,2,3,4],"objetivo":"Progressão gradual de volume dentro do objetivo hipertrofia."},{"id":"macro_2","nome":"Fase de Desenvolvimento","meses":[5,6],"objetivo":"Progressão gradual de intensidade dentro do objetivo hipertrofia."}]'::jsonb,
