  workout_generation_rules = '{"passo_1":"Identificar mes_atual = meses decorridos desde o início do plano do aluno.","passo_2":"Buscar mesociclo com ''mes'' == mes_atual.","passo_3":"Identificar semana corrente (1-4) dentro do mês.","passo_4":"Semana 4 -> usar ''semana_4_deload''; senão usar ''semanas_1_a_3'', pegar entrada com ''dia'' == dia do ciclo contínuo de 7 dias.","passo_5":"Se status==''treino'': montar sessão com exercícios do banco por grupos_musculares do dia, aplicando series/reps/%1RM/RPE do mesociclo ativo.","passo_6":"Se status!=''treino'': exibir texto de instrucao_app, sem prescrição de força.","passo_7":"Registrar RPE reportado pelo aluno para alimentar ajuste_individual."}'::jsonb,
  scientific_references = '["Schoenfeld, B.J. et al. (2017). Dose-response relationship between weekly resistance training volume and increases in muscle mass. J Sports Sci.","Kraemer, W.J. & Ratamess, N.A. (2004). Fundamentals of resistance training: progression and exercise prescription. Med Sci Sports Exerc.","Rhea, M.R. et al. (2003). A meta-analysis to determine the dose response for strength development. Med Sci Sports Exerc.","Israetel, M., Hoffmann, J., Smith, C.W. (2019). Scientific Principles of Hypertrophy Training. Renaissance Periodization.","American College of Sports Medicine (2009). Position Stand: Progression Models in Resistance Training for Healthy Adults."]'::jsonb,
